import { describe, expect, it } from 'vitest'
import { SplitValidationError, type SplitErrorCode } from './errors'
import {
  PLATFORM_FEE_BPS,
  computePlatformFee,
  computeSplit,
  type OrderSplit,
  type SplitLine,
} from './split'

// Fee oracle from the contract: Math.floor((subtotalCents * 75 + 5000) / 10000).
// Reference rows are hand-checked against that formula, not generated by it.

interface FeeCase {
  subtotalCents: number
  feeCents: number
}

interface SplitFailureCase {
  label: string
  lines: readonly SplitLine[]
  code: SplitErrorCode
  lineIndex: number | undefined
}

const FEE_REFERENCE: FeeCase[] = [
  { subtotalCents: 0, feeCents: 0 },
  { subtotalCents: 1, feeCents: 0 },
  { subtotalCents: 66, feeCents: 0 },
  { subtotalCents: 67, feeCents: 1 },
  { subtotalCents: 200, feeCents: 2 },
  { subtotalCents: 12000, feeCents: 90 },
  { subtotalCents: 13333, feeCents: 100 },
]

// subtotal * 75 / 10000 is an exact n.5 precisely when subtotal ≡ 200 (mod 400).
const FEE_EXACT_HALF_UP: FeeCase[] = [
  { subtotalCents: 200, feeCents: 2 },
  { subtotalCents: 600, feeCents: 5 },
  { subtotalCents: 1000, feeCents: 8 },
  { subtotalCents: 1400, feeCents: 11 },
  { subtotalCents: 1800, feeCents: 14 },
]

// Largest subtotal whose documented intermediate `subtotal * 75 + 5000` is still
// a safe integer. The contract only requires computePlatformFee to reject
// negatives and non-integers, so unsafe intermediates are asserted on computeSplit.
const LARGEST_EXACT_FEE_SUBTOTAL = 120_095_990_063_146
const LARGEST_EXACT_FEE_CENTS = 900_719_925_474

const FEE_LARGE: FeeCase[] = [
  { subtotalCents: 99_999_999, feeCents: 750_000 },
  { subtotalCents: 100_000_000, feeCents: 750_000 },
  { subtotalCents: 1_000_000_000_000, feeCents: 7_500_000_000 },
  {
    subtotalCents: LARGEST_EXACT_FEE_SUBTOTAL,
    feeCents: LARGEST_EXACT_FEE_CENTS,
  },
]

const FEE_REJECTED: number[] = [
  -1,
  -67,
  0.5,
  1.5,
  66.2,
  Number.NaN,
  Number.POSITIVE_INFINITY,
  Number.NEGATIVE_INFINITY,
]

// 1e14 * 75 stays inside MAX_SAFE_INTEGER. Two such lines make subtotal * 75 overflow
// even though each extension and the summed subtotal are still safe integers.
const FEE_SAFE_LINE_CENTS = 100_000_000_000_000
const FEE_SAFE_LINE_FEE_CENTS = 750_000_000_000

const UNSAFE_EXTENSION_QUANTITY = 10
const UNSAFE_EXTENSION_PRICE_CENTS = 1_000_000_000_000_000
const FIRST_UNSAFE_INTEGER = 2 ** 53

const SWEEP_ORDER_COUNT = 1000
const SWEEP_SEED = 0xc0ffee
const SWEEP_SEEDS_PER_ORDER = 12
const LCG_MULTIPLIER = 1664525
const LCG_INCREMENT = 1013904223

function thrownBy(run: () => void): unknown {
  try {
    run()
  } catch (caught: unknown) {
    return caught
  }
  return undefined
}

function expectSplitError(
  lines: readonly SplitLine[],
  code: SplitErrorCode,
  lineIndex: number | undefined,
): void {
  const thrown = thrownBy(() => {
    computeSplit(lines)
  })
  expect(thrown).toBeInstanceOf(Error)
  expect(thrown).toBeInstanceOf(SplitValidationError)
  if (!(thrown instanceof SplitValidationError)) {
    return
  }
  expect(thrown.name).toBe('SplitValidationError')
  expect(thrown.code).toBe(code)
  expect(thrown.lineIndex).toBe(lineIndex)
}

function expectFeeRejected(subtotalCents: number): void {
  const thrown = thrownBy(() => {
    computePlatformFee(subtotalCents)
  })
  expect(thrown).toBeInstanceOf(Error)
  expect(thrown).toBeInstanceOf(SplitValidationError)
  if (!(thrown instanceof SplitValidationError)) {
    return
  }
  expect(thrown.name).toBe('SplitValidationError')
  expect(thrown.code).toBe('INVALID_AMOUNT')
  // Not a line-scoped input, so the optional line index is absent.
  expect(thrown.lineIndex).toBeUndefined()
}

function expectOrder(lines: readonly SplitLine[], expected: OrderSplit): void {
  expect(computeSplit(lines)).toEqual(expected)
}

function nextLcg(seed: number): number {
  return (Math.imul(LCG_MULTIPLIER, seed) + LCG_INCREMENT) >>> 0
}

function seedAt(seeds: readonly number[], index: number): number {
  const value = seeds[index]
  if (value === undefined) {
    throw new Error(`No seed at index ${index}`)
  }
  return value
}

function buildLcgSeeds(count: number, seed: number): number[] {
  return Array.from({ length: count }).reduce<number[]>(
    (seeds, _slot, index) => {
      const previous = index === 0 ? seed : seedAt(seeds, index - 1)
      return [...seeds, nextLcg(previous)]
    },
    [],
  )
}

function buildSweepOrders(seeds: readonly number[]): SplitLine[][] {
  return Array.from({ length: SWEEP_ORDER_COUNT }, (_order, orderIndex) => {
    const offset = orderIndex * SWEEP_SEEDS_PER_ORDER
    const lineCount = (seedAt(seeds, offset) % 3) + 1
    return Array.from({ length: lineCount }, (_line, lineIndex) => {
      const base = offset + 1 + lineIndex * 3
      const quantity = (seedAt(seeds, base) % 5) + 1
      const unitCogsCents = seedAt(seeds, base + 1) % 50_000
      const unitPriceCents = unitCogsCents + (seedAt(seeds, base + 2) % 50_000)
      return { quantity, unitPriceCents, unitCogsCents }
    })
  })
}

describe('computePlatformFee', () => {
  it('exports the platform fee as 75 basis points', () => {
    expect(PLATFORM_FEE_BPS).toBe(75)
  })

  it.each(FEE_REFERENCE)(
    'charges $feeCents cents on a $subtotalCents cent subtotal',
    ({ subtotalCents, feeCents }) => {
      expect(computePlatformFee(subtotalCents)).toBe(feeCents)
    },
  )

  it.each(FEE_EXACT_HALF_UP)(
    'rounds an exact half cent up ($subtotalCents -> $feeCents)',
    ({ subtotalCents, feeCents }) => {
      expect(computePlatformFee(subtotalCents)).toBe(feeCents)
    },
  )

  it.each(FEE_LARGE)(
    'charges $feeCents cents on large subtotal $subtotalCents',
    ({ subtotalCents, feeCents }) => {
      expect(computePlatformFee(subtotalCents)).toBe(feeCents)
    },
  )

  it.each(FEE_REJECTED)(
    'rejects non-integer or negative subtotal %s',
    (subtotalCents) => {
      expectFeeRejected(subtotalCents)
    },
  )
})

describe('computeSplit', () => {
  it('splits a single line', () => {
    expectOrder([{ quantity: 1, unitPriceCents: 2500, unitCogsCents: 1000 }], {
      subtotalCents: 2500,
      platformFeeCents: 19,
      totalCents: 2519,
      cogsCents: 1000,
      providerMarginCents: 1500,
    })
  })

  it('sums multiple lines before charging the fee', () => {
    expectOrder(
      [
        { quantity: 1, unitPriceCents: 5000, unitCogsCents: 2000 },
        { quantity: 1, unitPriceCents: 3000, unitCogsCents: 1000 },
      ],
      {
        subtotalCents: 8000,
        platformFeeCents: 60,
        totalCents: 8060,
        cogsCents: 3000,
        providerMarginCents: 5000,
      },
    )
  })

  it('extends a line by quantity before splitting', () => {
    expectOrder([{ quantity: 3, unitPriceCents: 500, unitCogsCents: 200 }], {
      subtotalCents: 1500,
      platformFeeCents: 11,
      totalCents: 1511,
      cogsCents: 600,
      providerMarginCents: 900,
    })
  })

  it('allows a price equal to COGS and returns a zero provider margin', () => {
    expectOrder([{ quantity: 2, unitPriceCents: 400, unitCogsCents: 400 }], {
      subtotalCents: 800,
      platformFeeCents: 6,
      totalCents: 806,
      cogsCents: 800,
      providerMarginCents: 0,
    })
  })

  it('allows a zero price when COGS is zero', () => {
    expectOrder([{ quantity: 1, unitPriceCents: 0, unitCogsCents: 0 }], {
      subtotalCents: 0,
      platformFeeCents: 0,
      totalCents: 0,
      cogsCents: 0,
      providerMarginCents: 0,
    })
  })

  // FRONTEND_DESIGN §4.4 publishes totals only. One unit at those totals is the
  // smallest line list that produces them: subtotal $120.00, fee $0.90, patient
  // pays $120.90, COGS $70.00, margin $50.00.
  it('matches the order-builder example of $120.00 + $0.90 = $120.90', () => {
    expectOrder([{ quantity: 1, unitPriceCents: 12000, unitCogsCents: 7000 }], {
      subtotalCents: 12000,
      platformFeeCents: 90,
      totalCents: 12090,
      cogsCents: 7000,
      providerMarginCents: 5000,
    })
  })

  it('charges the fee on the order subtotal, not the sum of per-line fees', () => {
    // Each line is 67 cents, whose own fee is 1. Two of them summed per line
    // would be 2. The order subtotal is 134 cents, whose fee is 1.
    const lines: readonly SplitLine[] = [
      { quantity: 1, unitPriceCents: 67, unitCogsCents: 0 },
      { quantity: 1, unitPriceCents: 67, unitCogsCents: 0 },
    ]
    const perLineFeeSum = lines
      .map((line) =>
        Math.floor((line.quantity * line.unitPriceCents * 75 + 5000) / 10000),
      )
      .reduce((sum, fee) => sum + fee, 0)
    expect(perLineFeeSum).toBe(2)
    expectOrder(lines, {
      subtotalCents: 134,
      platformFeeCents: 1,
      totalCents: 135,
      cogsCents: 0,
      providerMarginCents: 134,
    })
  })

  it('does not depend on line order', () => {
    const first: SplitLine = {
      quantity: 2,
      unitPriceCents: 67,
      unitCogsCents: 10,
    }
    const second: SplitLine = {
      quantity: 1,
      unitPriceCents: 12000,
      unitCogsCents: 7000,
    }
    const third: SplitLine = {
      quantity: 4,
      unitPriceCents: 250,
      unitCogsCents: 250,
    }
    const lines: readonly SplitLine[] = [first, second, third]
    const orders = [
      lines,
      Array.from(lines).reverse(),
      [second, third, first],
      [third, first, second],
    ]
    const splits = orders.map((order) => computeSplit(order))
    splits.forEach((split) => {
      expect(split).toEqual(splits[0])
    })
  })

  it('accepts the largest subtotal the documented fee formula can compute exactly', () => {
    expectOrder(
      [
        {
          quantity: 1,
          unitPriceCents: LARGEST_EXACT_FEE_SUBTOTAL,
          unitCogsCents: 0,
        },
      ],
      {
        subtotalCents: LARGEST_EXACT_FEE_SUBTOTAL,
        platformFeeCents: LARGEST_EXACT_FEE_CENTS,
        totalCents: LARGEST_EXACT_FEE_SUBTOTAL + LARGEST_EXACT_FEE_CENTS,
        cogsCents: 0,
        providerMarginCents: LARGEST_EXACT_FEE_SUBTOTAL,
      },
    )
  })

  it('accepts one line whose own fee intermediate is still exact', () => {
    expectOrder(
      [{ quantity: 1, unitPriceCents: FEE_SAFE_LINE_CENTS, unitCogsCents: 0 }],
      {
        subtotalCents: FEE_SAFE_LINE_CENTS,
        platformFeeCents: FEE_SAFE_LINE_FEE_CENTS,
        totalCents: FEE_SAFE_LINE_CENTS + FEE_SAFE_LINE_FEE_CENTS,
        cogsCents: 0,
        providerMarginCents: FEE_SAFE_LINE_CENTS,
      },
    )
  })
})

describe('computeSplit validation', () => {
  // Single pass, table order, first offense wins. On each line: quantity, then
  // amounts, then price-vs-COGS, then that line's extensions and the running
  // subtotal. UNSAFE_AMOUNT is last in the table, so it loses to an input-validation
  // failure on the same line, but an earlier line's overflow is already an offense
  // and beats a later line's invalid quantity. EMPTY_ORDER has no line index.
  // An integer above Number.MAX_SAFE_INTEGER (2 ** 53) is not INVALID_AMOUNT or
  // INVALID_QUANTITY — those are non-integers, negatives, NaN/Infinity, and
  // quantities below 1. It is UNSAFE_AMOUNT. lineIndex is the first line whose
  // extension, or whose addition into the subtotal, makes an intermediate
  // (including subtotal * 75 + 5000) or a final field exceed MAX_SAFE_INTEGER.
  const failures: SplitFailureCase[] = [
    {
      label: 'empty order',
      lines: [],
      code: 'EMPTY_ORDER',
      lineIndex: undefined,
    },
    {
      label: 'zero quantity',
      lines: [{ quantity: 0, unitPriceCents: 100, unitCogsCents: 40 }],
      code: 'INVALID_QUANTITY',
      lineIndex: 0,
    },
    {
      label: 'negative quantity',
      lines: [{ quantity: -3, unitPriceCents: 100, unitCogsCents: 40 }],
      code: 'INVALID_QUANTITY',
      lineIndex: 0,
    },
    {
      label: 'fractional quantity',
      lines: [{ quantity: 1.5, unitPriceCents: 100, unitCogsCents: 40 }],
      code: 'INVALID_QUANTITY',
      lineIndex: 0,
    },
    {
      label: 'NaN quantity',
      lines: [{ quantity: Number.NaN, unitPriceCents: 100, unitCogsCents: 40 }],
      code: 'INVALID_QUANTITY',
      lineIndex: 0,
    },
    {
      label: 'infinite quantity',
      lines: [
        {
          quantity: Number.POSITIVE_INFINITY,
          unitPriceCents: 100,
          unitCogsCents: 40,
        },
      ],
      code: 'INVALID_QUANTITY',
      lineIndex: 0,
    },
    {
      label: 'negative infinite quantity',
      lines: [
        {
          quantity: Number.NEGATIVE_INFINITY,
          unitPriceCents: 100,
          unitCogsCents: 40,
        },
      ],
      code: 'INVALID_QUANTITY',
      lineIndex: 0,
    },
    {
      label: 'invalid quantity on a later line',
      lines: [
        { quantity: 1, unitPriceCents: 100, unitCogsCents: 40 },
        { quantity: 0, unitPriceCents: 100, unitCogsCents: 40 },
      ],
      code: 'INVALID_QUANTITY',
      lineIndex: 1,
    },
    {
      label: 'negative unit price',
      lines: [{ quantity: 1, unitPriceCents: -1, unitCogsCents: 0 }],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'negative unit COGS',
      lines: [{ quantity: 1, unitPriceCents: 100, unitCogsCents: -1 }],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'fractional unit price',
      lines: [{ quantity: 1, unitPriceCents: 100.5, unitCogsCents: 40 }],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'fractional unit COGS',
      lines: [{ quantity: 1, unitPriceCents: 100, unitCogsCents: 40.5 }],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'NaN unit price',
      lines: [{ quantity: 1, unitPriceCents: Number.NaN, unitCogsCents: 40 }],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'NaN unit COGS',
      lines: [{ quantity: 1, unitPriceCents: 100, unitCogsCents: Number.NaN }],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'infinite unit price',
      lines: [
        {
          quantity: 1,
          unitPriceCents: Number.POSITIVE_INFINITY,
          unitCogsCents: 40,
        },
      ],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'negative infinite unit COGS',
      lines: [
        {
          quantity: 1,
          unitPriceCents: 100,
          unitCogsCents: Number.NEGATIVE_INFINITY,
        },
      ],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'invalid amount on a later line',
      lines: [
        { quantity: 1, unitPriceCents: 100, unitCogsCents: 40 },
        { quantity: 1, unitPriceCents: 100, unitCogsCents: -5 },
      ],
      code: 'INVALID_AMOUNT',
      lineIndex: 1,
    },
    {
      label: 'unit price below unit COGS',
      lines: [{ quantity: 1, unitPriceCents: 100, unitCogsCents: 101 }],
      code: 'PRICE_BELOW_COGS',
      lineIndex: 0,
    },
    {
      label: 'price below COGS on a later line',
      lines: [
        { quantity: 1, unitPriceCents: 100, unitCogsCents: 100 },
        { quantity: 2, unitPriceCents: 50, unitCogsCents: 51 },
      ],
      code: 'PRICE_BELOW_COGS',
      lineIndex: 1,
    },
    {
      label: 'invalid quantity wins over invalid amount and price below COGS',
      lines: [{ quantity: 0, unitPriceCents: -5, unitCogsCents: 10 }],
      code: 'INVALID_QUANTITY',
      lineIndex: 0,
    },
    {
      label: 'invalid amount wins over price below COGS',
      lines: [{ quantity: 1, unitPriceCents: 10.5, unitCogsCents: 20 }],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'an earlier price-below-COGS wins over a later invalid quantity',
      lines: [
        { quantity: 1, unitPriceCents: 10, unitCogsCents: 11 },
        { quantity: 0, unitPriceCents: 10, unitCogsCents: 1 },
      ],
      code: 'PRICE_BELOW_COGS',
      lineIndex: 0,
    },
    {
      label: 'an earlier invalid amount wins over a later invalid quantity',
      lines: [
        { quantity: 1, unitPriceCents: -1, unitCogsCents: 0 },
        { quantity: 0, unitPriceCents: 100, unitCogsCents: 0 },
      ],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label:
        'a later line reports invalid quantity before its own invalid amount',
      lines: [
        { quantity: 1, unitPriceCents: 100, unitCogsCents: 40 },
        { quantity: -2, unitPriceCents: 1.5, unitCogsCents: 50 },
      ],
      code: 'INVALID_QUANTITY',
      lineIndex: 1,
    },
    {
      label: 'invalid quantity wins over an unsafe price on the same line',
      lines: [
        {
          quantity: 1.5,
          unitPriceCents: FIRST_UNSAFE_INTEGER,
          unitCogsCents: 0,
        },
      ],
      code: 'INVALID_QUANTITY',
      lineIndex: 0,
    },
    {
      label: 'invalid amount wins over an unsafe quantity',
      lines: [
        {
          quantity: FIRST_UNSAFE_INTEGER,
          unitPriceCents: -1,
          unitCogsCents: 0,
        },
      ],
      code: 'INVALID_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'price below COGS wins over an extension that would overflow',
      lines: [
        {
          quantity: UNSAFE_EXTENSION_QUANTITY,
          unitPriceCents: UNSAFE_EXTENSION_PRICE_CENTS,
          unitCogsCents: UNSAFE_EXTENSION_PRICE_CENTS * 2,
        },
      ],
      code: 'PRICE_BELOW_COGS',
      lineIndex: 0,
    },
    {
      label: 'unit price above the safe integer range',
      lines: [
        { quantity: 1, unitPriceCents: FIRST_UNSAFE_INTEGER, unitCogsCents: 0 },
      ],
      code: 'UNSAFE_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'quantity above the safe integer range',
      lines: [
        { quantity: FIRST_UNSAFE_INTEGER, unitPriceCents: 1, unitCogsCents: 0 },
      ],
      code: 'UNSAFE_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'line extension above the safe integer range',
      lines: [
        {
          quantity: UNSAFE_EXTENSION_QUANTITY,
          unitPriceCents: UNSAFE_EXTENSION_PRICE_CENTS,
          unitCogsCents: 0,
        },
      ],
      code: 'UNSAFE_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'unsafe extension on a later line',
      lines: [
        { quantity: 1, unitPriceCents: 100, unitCogsCents: 40 },
        {
          quantity: UNSAFE_EXTENSION_QUANTITY,
          unitPriceCents: UNSAFE_EXTENSION_PRICE_CENTS,
          unitCogsCents: 0,
        },
      ],
      code: 'UNSAFE_AMOUNT',
      lineIndex: 1,
    },
    {
      label: 'fee intermediate overflows one cent past the exact formula limit',
      lines: [
        {
          quantity: 1,
          unitPriceCents: LARGEST_EXACT_FEE_SUBTOTAL + 1,
          unitCogsCents: 0,
        },
      ],
      code: 'UNSAFE_AMOUNT',
      lineIndex: 0,
    },
    {
      label: 'fee intermediate overflows only after the second safe line',
      lines: [
        { quantity: 1, unitPriceCents: FEE_SAFE_LINE_CENTS, unitCogsCents: 0 },
        { quantity: 1, unitPriceCents: FEE_SAFE_LINE_CENTS, unitCogsCents: 0 },
      ],
      code: 'UNSAFE_AMOUNT',
      lineIndex: 1,
    },
    {
      label: 'an earlier unsafe extension wins over a later invalid quantity',
      lines: [
        {
          quantity: UNSAFE_EXTENSION_QUANTITY,
          unitPriceCents: UNSAFE_EXTENSION_PRICE_CENTS,
          unitCogsCents: 0,
        },
        { quantity: 0, unitPriceCents: 100, unitCogsCents: 0 },
      ],
      code: 'UNSAFE_AMOUNT',
      lineIndex: 0,
    },
  ]

  it.each(failures)('$label', ({ lines, code, lineIndex }) => {
    expectSplitError(lines, code, lineIndex)
  })
})

describe('split sum invariants', () => {
  it('holds for a seeded sweep of 1000 valid orders', () => {
    // Numerical Recipes LCG, modulus 2^32. Amounts stay small so the documented
    // fee formula is exact. The two sum identities alone would accept an all-zero
    // split, so the sweep also checks the field definitions.
    const seeds = buildLcgSeeds(
      SWEEP_ORDER_COUNT * SWEEP_SEEDS_PER_ORDER,
      SWEEP_SEED,
    )
    const orders = buildSweepOrders(seeds)
    expect(orders).toHaveLength(SWEEP_ORDER_COUNT)
    orders.forEach((lines) => {
      expect(lines.length).toBeGreaterThan(0)
      const subtotalCents = lines.reduce(
        (sum, line) => sum + line.quantity * line.unitPriceCents,
        0,
      )
      const cogsCents = lines.reduce(
        (sum, line) => sum + line.quantity * line.unitCogsCents,
        0,
      )
      const split = computeSplit(lines)
      const fields = [
        split.subtotalCents,
        split.platformFeeCents,
        split.totalCents,
        split.cogsCents,
        split.providerMarginCents,
      ]
      fields.forEach((field) => {
        expect(Number.isSafeInteger(field)).toBe(true)
        expect(field).toBeGreaterThanOrEqual(0)
      })
      expect(split.subtotalCents).toBe(subtotalCents)
      expect(split.cogsCents).toBe(cogsCents)
      expect(split.providerMarginCents).toBe(subtotalCents - cogsCents)
      expect(split.platformFeeCents).toBe(
        Math.floor((subtotalCents * 75 + 5000) / 10000),
      )
      expect(split.subtotalCents + split.platformFeeCents).toBe(
        split.totalCents,
      )
      expect(
        split.cogsCents + split.providerMarginCents + split.platformFeeCents,
      ).toBe(split.totalCents)
    })
  })
})
